import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import tailwindcss from '@tailwindcss/vite';
import { VitePWA } from 'vite-plugin-pwa';
import path from 'node:path';
import fs from 'node:fs';

// PWA icon set: the real PNG icons are generated by a sibling agent into
// public/icons/. If they are missing at build time we fall back to a
// temporary inline SVG so the build never breaks.
const iconsDir = path.resolve(__dirname, 'public/icons');
const hasPng = (f: string) => fs.existsSync(path.join(iconsDir, f));
const pngIconsReady = ['icon-192.png', 'icon-512.png', 'maskable-512.png', 'apple-touch-icon.png'].every(hasPng);

const manifestIcons = pngIconsReady
  ? [
      { src: 'icons/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: 'icons/icon-512.png', sizes: '512x512', type: 'image/png' },
      { src: 'icons/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ]
  : [{ src: 'icons/fallback-icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' }];

export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
    VitePWA({
      registerType: 'autoUpdate',
      includeAssets: ['icons/fallback-icon.svg'],
      manifest: {
        name: 'BrandForge AI',
        short_name: 'BrandForge',
        description: 'Agentic AI platform for marketing and branding',
        theme_color: '#6D28D9',
        background_color: '#0F172A',
        display: 'standalone',
        start_url: '/',
        icons: manifestIcons,
      },
      workbox: {
        globPatterns: ['**/*.{js,css,html,ico,png,svg,woff2}'],
      },
    }),
  ],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, 'src'),
      '@brandforge/ui': path.resolve(__dirname, '../../packages/ui/src/index.ts'),
      '@brandforge/shared': path.resolve(__dirname, '../../packages/shared/src/index.ts'),
    },
  },
  server: {
    port: 5173,
  },
});
